from itertools import combinations

def slow(A, T):                    # brute force: build all 2^N subsets, then filter
    out = []
    for size in range(len(A) + 1):
        for combo in combinations(sorted(A), size):
            if sum(combo) == T:
                out.append(list(combo))
    return sorted(out)

def fast(A, T):                    # backtracking: stop a branch once it is too big
    A = sorted(A)
    out, path = [], []
    def go(start, left):
        if left == 0:
            out.append(path[:])
            return
        for i in range(start, len(A)):
            if A[i] > left:        # sorted, so every later number is too big too
                break
            path.append(A[i])
            go(i + 1, left - A[i])
            path.pop()
    go(0, T)
    return sorted(out)

for A, T in [([2, 3, 5, 6, 8], 8), ([1, 2, 3], 7)]:
    print(slow(A, T), fast(A, T))  # -> [[2, 6], [3, 5], [8]] [[2, 6], [3, 5], [8]], then [] []
